 static string JsonValue(object value){if(value==null)return "null";if(value is bool)return (bool)value?"true":"false";if(value is int)return value.ToString();var dict=value as IDictionary;if(dict!=null){var rows=new List<string>();foreach(DictionaryEntry row in dict)rows.Add(Q(row.Key)+":"+JsonValue(row.Value));return "{"+String.Join(",",rows.ToArray())+"}";}var list=value as IList;if(list!=null){var rows=new List<string>();foreach(object row in list)rows.Add(JsonValue(row));return "["+String.Join(",",rows.ToArray())+"]";}return Q(value);}
 public static void Boot(){try{if(instance!=null)return;string dir=Path.Combine(Application.dataPath,"cw3-debug");string enable=Path.Combine(dir,"enabled.txt");if(!File.Exists(enable))return;string expected=File.ReadAllText(enable).Trim();string actual=Hash(Path.Combine(Application.dataPath,"Managed/Assembly-CSharp.dll"));if(expected.Length!=64||expected!=actual)return;var go=new GameObject("CW3Debug (explicitly enabled)");DontDestroyOnLoad(go);instance=go.AddComponent<CW3Debug>();instance.root=dir;File.WriteAllText(Path.Combine(dir,"ready.json"),"{\"enabled\":true,\"assembly_sha256\":"+Q(actual)+"}");}catch(Exception e){Debug.Log("[CW3Debug] boot failed: "+e.GetType().Name);}}
