 string AtlasProbe(){
  Type rt=Type.GetType("CW3Runtime, CW3Runtime",true);var values=(IDictionary)rt.GetField("translations",flags).GetValue(null);var chars=new Dictionary<char,bool>();foreach(DictionaryEntry row in values)foreach(char c in (string)row.Value)if(!Char.IsWhiteSpace(c))chars[c]=true;var text=new StringBuilder();foreach(char c in chars.Keys)text.Append(c);
  var used=new List<Font>();Type styles=rt.Assembly.GetType("TextStyles");if(styles!=null){var owned=(IDictionary)styles.GetField("fonts",flags).GetValue(null);foreach(DictionaryEntry row in owned)if(row.Value is Font&&!used.Contains((Font)row.Value))used.Add((Font)row.Value);}else foreach(string name in new[]{"external","guiExternal"}){var f=rt.GetField(name,flags).GetValue(null) as Font;if(f!=null&&!used.Contains(f))used.Add(f);}
  var rows=new ArrayList();foreach(Font font in used){int notifications=0;Action<Font> observer=delegate(Font changed){if(changed==font)notifications++;};var before=font.material.mainTexture;string beforeSize=before==null?"missing":before.width+"x"+before.height;Font.textureRebuilt+=observer;try{font.RequestCharactersInTexture(text.ToString(),font.fontSize,FontStyle.Normal);}finally{Font.textureRebuilt-=observer;}var after=font.material.mainTexture;rows.Add(new Hashtable{{"font",font.name},{"font_id",font.GetInstanceID()},{"size",font.fontSize},{"glyphs_requested",chars.Count},{"before_texture",beforeSize},{"after_texture",after==null?"missing":after.width+"x"+after.height},{"rebuild_events",notifications}});}return JsonValue(new Hashtable{{"scene",Application.loadedLevelName},{"scope","actual loaded translations; owned fonts only"},{"fonts",rows}});
 }
